/**
 * A bare aggregate that is the whole HAVING condition must be lifted into the Group/Extension exactly like an aggregate
 * nested inside a larger condition: the Filter condition becomes the generated variable, never the aggregate itself.
 */
class HavingRootAggregateParserTest {

	private static final String PREFIX = "PREFIX agg: <http://rdf4j.org/aggregate#> PREFIX ex: <http://ex/> ";

	/**
	 * The real {@code agg:} factories live in queryalgebra-evaluation, which is not on this module's test classpath, so
	 * {@code agg:boolAnd} is registered here as a dummy unary aggregate: the parser only needs the IRI to be known.
	 */
	private static final AggregateFunctionFactory BOOL_AND = new AggregateFunctionFactory() {
		@Override
		public String getIri() {
			return "http://rdf4j.org/aggregate#boolAnd";
		}

		@Override
		public AggregateFunction buildFunction(Function<BindingSet, Value> evaluationStep) {
			return null;
		}

		@Override
		public AggregateCollector getCollector() {
			return null;
		}
	};

	@BeforeAll
	static void registerDummyAggregate() {
		CustomAggregateFunctionRegistry.getInstance().add(BOOL_AND);
	}

	@AfterAll
	static void unregisterDummyAggregate() {
		CustomAggregateFunctionRegistry.getInstance().remove(BOOL_AND);
	}

	private static TupleExpr parse(String query) {
		TupleExpr expr = ((ParsedTupleQuery) new SPARQLParser().parseQuery(PREFIX + query, null)).getTupleExpr();
		return expr instanceof QueryRoot root ? root.getArg() : expr;
	}

	private static <T> List<T> collect(TupleExpr expr, Class<T> type) {
		List<T> found = new ArrayList<>();
		expr.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Filter node) {
				if (type.isInstance(node)) {
					found.add(type.cast(node));
				}
				super.meet(node);
			}

			@Override
			public void meet(Group node) {
				if (type.isInstance(node)) {
					found.add(type.cast(node));
				}
				super.meet(node);
			}

			@Override
			public void meet(Extension node) {
				if (type.isInstance(node)) {
					found.add(type.cast(node));
				}
				super.meet(node);
			}
		});
		return found;
	}

	private static void assertRootAggregateIsLifted(String query, Class<? extends AggregateOperator> aggregate) {
		TupleExpr expr = parse(query);

		List<Filter> filters = collect(expr, Filter.class);
		assertThat(filters).as("HAVING filters in " + query).hasSize(1);
		ValueExpr condition = filters.get(0).getCondition();
		assertThat(condition).as("HAVING condition of " + query).isInstanceOf(Var.class);
		String name = ((Var) condition).getName();

		List<Group> groups = collect(expr, Group.class);
		assertThat(groups).hasSize(1);
		List<GroupElem> groupElems = groups.get(0).getGroupElements();
		assertThat(groupElems).as("group elements of " + query).hasSize(1);
		assertThat(groupElems.get(0).getName()).isEqualTo(name);
		assertThat(groupElems.get(0).getOperator()).isInstanceOf(aggregate);

		List<Extension> extensions = collect(expr, Extension.class);
		assertThat(extensions).isNotEmpty();
		List<ExtensionElem> matching = new ArrayList<>();
		for (Extension extension : extensions) {
			for (ExtensionElem elem : extension.getElements()) {
				if (elem.getName().equals(name)) {
					matching.add(elem);
				}
			}
		}
		assertThat(matching).as("extension element binding " + name).hasSize(1);
		assertThat(matching.get(0).getExpr()).isInstanceOf(aggregate);
	}

	@Test
	void bareStandardAggregateAsHavingConditionIsLifted() {
		assertRootAggregateIsLifted("SELECT ?dept WHERE { ?e ex:dept ?dept ; ex:active ?a }"
				+ " GROUP BY ?dept HAVING (SAMPLE(?a))", Sample.class);
	}

	@Test
	void bareCustomAggregateAsHavingConditionIsLifted() {
		assertRootAggregateIsLifted("SELECT ?dept WHERE { ?e ex:dept ?dept ; ex:active ?a }"
				+ " GROUP BY ?dept HAVING (agg:boolAnd(?a))", AggregateFunctionCall.class);
	}

	@Test
	void nestedAggregateInHavingConditionStaysLifted() {
		// the already-working nested shape: the Filter condition is a comparison whose operand is the lifted variable
		TupleExpr expr = parse("SELECT ?dept WHERE { ?e ex:dept ?dept ; ex:active ?a }"
				+ " GROUP BY ?dept HAVING (agg:boolAnd(?a) = true)");
		List<Filter> filters = collect(expr, Filter.class);
		assertThat(filters).hasSize(1);
		List<AggregateOperator> inCondition = new ArrayList<>();
		filters.get(0).getCondition().visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(AggregateFunctionCall node) {
				inCondition.add(node);
			}
		});
		assertThat(inCondition).isEmpty();
	}
}
